#!/bin/bashset -ecat > /home/z/my-project/src/app/page.tsx << 'ENDOFFILE''use client'import { useEffect, useState } from 'react'import { useCartStore } from '@/store/cart-store'import { useViewStore, ViewType } from '@/store/view-store'import ProductCatalog from '@/components/product-catalog'import ShoppingCart from '@/components/shopping-cart'import Checkout from '@/components/checkout'import OrderSuccess from '@/components/order-success'import AdminPanel from '@/components/admin-panel'import { Button } from '@/components/ui/button'import { ShoppingCart, Store, ShieldCheck, Package } from 'lucide-react'const navItems: { label: string; view: ViewType; icon: React.ReactNode; admin?: boolean }[] = [  { label: 'Shop', view: 'catalog', icon: <Store className="h-4 w-4" /> },  { label: 'Cart', view: 'cart', icon: <ShoppingCart className="h-4 w-4" /> },  { label: 'Admin', view: 'admin', icon: <ShieldCheck className="h-4 w-4" />, admin: true },]function CartBadge() {  const getTotalItems = useCartStore((s) => s.getTotalItems)  const [count, setCount] = useState(0)  useEffect(() => {    setCount(getTotalItems())    const unsub = useCartStore.subscribe(() => setCount(getTotalItems()))    return unsub  }, [getTotalItems])  if (count === 0) return null  return (    <span className="absolute -top-1.5 -right-1.5 flex h-4 w-4 items-center justify-center rounded-full bg-primary text-[9px] font-bold text-primary-foreground">      {count > 99 ? '99+' : count}    </span>  )}export default function Home() {  const currentView = useViewStore((s) => s.currentView)  const navigate = useViewStore((s) => s.navigate)  const [mounted, setMounted] = useState(false)  useEffect(() => { setMounted(true)    fetch('/api/seed', { method: 'POST' }).catch(() => {})  }, [])  if (!mounted) return (    <div className="min-h-screen flex items-center justify-center">      <div className="flex flex-col items-center gap-4">        <div className="h-10 w-10 rounded-full border-4 border-primary border-t-transparent animate-spin" />        <p className="text-muted-foreground text-sm">Loading ShopNest...</p>      </div>    </div>  )  const renderView = () => {    switch (currentView) {      case 'catalog': return <ProductCatalog />      case 'cart': return <ShoppingCart />      case 'checkout': return <Checkout />      case 'order-success': return <OrderSuccess />      case 'admin':      case 'admin-products':      case 'admin-orders': return <AdminPanel />      default: return <ProductCatalog />    }  }  return (    <div className="min-h-screen flex flex-col bg-background">      {/* Navigation Header */}      <header className="sticky top-0 z-50 w-full border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">        <div className="container mx-auto flex h-14 max-w-7xl items-center px-4">          <button            className="mr-6 flex items-center gap-2 font-bold text-lg"            onClick={() => navigate('catalog')}          >            <Package className="h-5 w-5 text-primary" />            <span className="hidden sm:inline">ShopNest</span>          </button>          <nav className="flex items-center gap-1">            {navItems.map((item) => (              <Button                key={item.view}                variant={currentView === item.view || (item.view === 'admin' && currentView.startsWith('admin')) ? 'secondary' : 'ghost'}                size="sm"                className="relative gap-2"                onClick={() => navigate(item.view)}              >                {item.icon}                <span className="hidden sm:inline">{item.label}</span>                {item.view === 'cart' && <CartBadge />}              </Button>            ))}          </nav>        </div>      </header>      {/* Main Content */}      <main className="flex-1 container mx-auto max-w-7xl px-4 py-6">        {renderView()}      </main>      {/* Footer */}      <footer className="border-t mt-auto">        <div className="container mx-auto max-w-7xl px-4 py-6">          <div className="flex flex-col items-center justify-between gap-4 sm:flex-row">            <div className="flex items-center gap-2 text-sm text-muted-foreground">              <Package className="h-4 w-4" />              <span>ShopNest E-Commerce Platform</span>            </div>            <p className="text-xs text-muted-foreground">              Built with Next.js, Prisma, Zustand & shadcn/ui          </p>          </div>        </div>      </footer>    </div>  )}ENDOFFILEecho "Created page.tsx"